SELECT CAST(SUM(CASE WHEN v.Venue_Name LIKE '%M Chinnaswamy%' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN v.Venue_Name LIKE '%Maharashtra Cricket Association%' THEN 1 ELSE 0 END) AS difference
FROM Match m
JOIN Venue v ON m.Venue_Id = v.Venue_Id;

SELECT COUNT(*) AS match_count
FROM Ball_by_Ball
WHERE Innings_No = 2;

SELECT COUNT(*) AS total_players
FROM Player
WHERE strftime('%Y', DOB) BETWEEN '1970' AND '1975';

SELECT JobTitle AS "Job Position"
FROM Employee
WHERE BirthDate = (
    SELECT MIN(BirthDate)
    FROM Employee
);

SELECT COUNT(*) AS EmployeeCount
FROM EmployeePayHistory
WHERE PayFrequency = 1 AND Rate > 50;

SELECT p.FirstName || ' ' || COALESCE(p.MiddleName, '') || ' ' || p.LastName AS Full_Name
FROM Person p
WHERE p.BusinessEntityID = 1;

SELECT Vendor.BusinessEntityID, Vendor.Name AS CompanyName
FROM Vendor
WHERE Vendor.CreditRating = 5;

SELECT COUNT(CASE WHEN c.Name = 'English' THEN 1 END) - COUNT(CASE WHEN c.Name = 'Arabic' THEN 1 END) AS difference
FROM ProductModelProductDescriptionCulture pmcdc
JOIN Culture c ON pmcdc.CultureID = c.CultureID;

SELECT Person.BusinessEntityID 
FROM Person 
WHERE FirstName = 'Emma' AND LastName = 'Harris';

SELECT TOP 1 Name AS ProductName, Rating AS ReviewScore
FROM ProductReview
ORDER BY Rating DESC, ProductReviewID ASC;

SELECT MIN(SafetyStockLevel) AS MinInventoryQuantity
FROM Product
WHERE LOWER(Name) LIKE '%chainring%';

SELECT playerID AS "Player ID", coachID AS "Coach ID"
FROM Master
WHERE playerID IS NOT NULL AND coachID IS NOT NULL;

SELECT e.Service * e.GDP AS Service_of_GDP
FROM economy e
WHERE LOWER(e.Country) = 'brazil';

SELECT Country, Population AS "Population", Population_Growth AS "Growth"
FROM population
WHERE Population_Growth < 0;

SELECT Country1, Country2
FROM borders
WHERE Length = 803;

SELECT CAST(COUNT(*) AS REAL) * 100.0 / (SELECT COUNT(*) FROM country) AS percentage
FROM politics
WHERE strftime('%Y', Independence) = '1960';
